// Generated by build/mockups/temi/dart_table.py from the approved themes; edit there, not here.
// The dark twins come from dark_colours.dart (build/mockups/tema_scuro/dark_table.py).

enum ColourTheme
{
  casaMichela('CASA_MICHELA'),
  cobalto('COBALTO'),
  ardesia('ARDESIA'),
  lavanda('LAVANDA'),
  confetto('CONFETTO'),
  terracotta('TERRACOTTA');

  // As the API names it.
  final String key;

  const ColourTheme(this.key);

  static ColourTheme fromKey(String? key) =>
      values.firstWhere((theme) => theme.key == key, orElse: () => casaMichela);
}

// The theme in force: the signed-in account's, Casa Michela before sign-in.
abstract final class ThemeColours
{
  static final ValueNotifier<ColourTheme> current = ValueNotifier(ColourTheme.casaMichela);

  // The account's dark mode; light before sign-in, like the colours.
  static final ValueNotifier<bool> dark = ValueNotifier(false);

  static ColourTheme? _forced;
  static bool? _forcedDark;

  static ColourTheme get _painting => _forced ?? current.value;

  static bool get isDark => _forcedDark ?? dark.value;

  // A Casa Michela colour as the theme in force paints it, its dark twin in the dark; alpha is kept.
  static Color of(int argb)
  {
    final List<int>? night = isDark ? darkRows[argb & 0xFFFFFF] : null;

    return night == null ? keep(argb) : Color((argb & 0xFF000000) | night[_painting.index]);
  }

  // The theme's colour even in the dark: fills under white text, light text on the accents, previews.
  static Color keep(int argb)
  {
    final List<int>? row = _painting == ColourTheme.casaMichela ? null : _rows[argb & 0xFFFFFF];

    return Color(row == null ? argb : (argb & 0xFF000000) | row[_painting.index - 1]);
  }

  // A colour no theme changes, darkened in the dark.
  static Color fixed(int argb)
  {
    final int? night = isDark ? darkFixed[argb & 0xFFFFFF] : null;

    return Color(night == null ? argb : (argb & 0xFF000000) | night);
  }

  // A deep accent written as text, icon or line: lit up in the dark to read on the dark cards.
  static Color lit(int argb)
  {
    final List<int>? night = isDark ? litRows[argb & 0xFFFFFF] : null;

    return night == null ? keep(argb) : Color((argb & 0xFF000000) | night[_painting.index]);
  }

  // The same for a deep accent no theme changes.
  static Color fixedLit(int argb)
  {
    final List<int>? night = isDark ? litRows[argb & 0xFFFFFF] : null;

    return Color(night == null ? argb : (argb & 0xFF000000) | night[0]);
  }

  // Reads colours as [theme] paints them, in [dark] if given: swatches, a sea changing theme, PDFs.
  static T painted<T>(ColourTheme theme, T Function() read, {bool? dark})
  {
    final ColourTheme? forced = _forced;
    final bool? forcedDark = _forcedDark;
    _forced = theme;
    _forcedDark = dark ?? _forcedDark;

    try
    {
      return read();
    }
    finally
    {
      _forced = forced;
      _forcedDark = forcedDark;
    }
  }

  // What leaves the app (PDFs) keeps Casa Michela's light colours.
  static T inCasaMichela<T>(T Function() read) => painted(ColourTheme.casaMichela, read, dark: false);

  // Presence stays green in every theme, only nudged towards it.
  static Color get presenceAccent => _pick(_presenceAccent);
  static Color get presenceAccentText => isDark ? _pick(darkPresenceAccentText) : presenceAccent;
  static Color get presenceSurface => _pick(isDark ? darkPresenceSurface : _presenceSurface);

  // The dark page; the phone's sea sinks toward darkSea in the dark.
  static Color get darkPage => const Color(0xFF000000 | darkPageRgb);
  static Color get darkSea => const Color(0xFF000000 | darkSeaRgb);

  // The top of the phone's sea; elsewhere the deep water stays Casa Michela's.
  static Color get seaTop => _pick(_seaTop);

  // The greeting's colour beside the ocean, shared by the dismiss buttons: far from the theme's own and the ocean.
  static Color get secondAccent => _pick(_secondAccent);
  static Color get secondAccentText => _pick(isDark ? _secondAccentLit : _secondAccent);

  static Color _pick(List<int> values) => Color(0xFF000000 | values[_painting.index]);
}

